/*
 * HX711 Load Cell Weight Sensor
 *
 * Wiring:
 *   Load Cell E+ -> HX711 E+
 *   Load Cell E- -> HX711 E-
 *   Load Cell A+ -> HX711 A+
 *   Load Cell A- -> HX711 A-
 *   HX711 VCC -> 5V
 *   HX711 GND -> GND
 *   HX711 DT  -> D3
 *   HX711 SCK -> D2
 *
 * Reads weight from a load cell via the HX711 amplifier.
 * Use the interactive weight slider on the load cell
 * to change the weight value in real time.
 */

#include "HX711.h"

HX711 scale(3, 2); // DT=3, SCK=2

// Calibration factor - adjust for your load cell
float calibration_factor = 2280.0;

void setup() {
  Serial.begin(9600);
  Serial.println("HX711 Load Cell Weight Sensor");
  Serial.println("-----------------------------");

  scale.set_scale(calibration_factor);
  scale.tare();

  Serial.println("Tare done. Place object on scale.");
  Serial.println();
}

void loop() {
  float weight = scale.get_units();

  Serial.print("Weight: ");
  Serial.print(weight, 2);
  Serial.println(" g");

  delay(500);
}
